<?php
require __DIR__ . '/../../app/bootstrap.php';
require_admin();
$id = (int)($_GET['id'] ?? 0);
$log = $id ? find_log($id,true) : ['title'=>'','description'=>'','log_date'=>date('Y-m-d'),'status'=>'planned','progress'=>0,'blocker_note'=>'','links'=>'','visibility'=>'public','category_id'=>''];
if (!$log) { http_response_code(404); exit('Catatan tidak ditemukan.'); }
$errors = $_SESSION['form_errors'] ?? [];
$old = $_SESSION['form_old'] ?? null;
if ($old && (int)($old['id'] ?? 0) === $id) $log = [...$log,...$old];
unset($_SESSION['form_errors'],$_SESSION['form_old']);
page_start($id ? 'Edit catatan' : 'Catatan baru','admin');
?>
<a class="back-link" href="<?= e(url('admin/')) ?>">← Kembali ke catatan</a><section class="page-heading"><div><div class="eyebrow">DOKUMENTASIKAN LANGKAHMU</div><h1><?= $id ? 'Edit catatan' : 'Catatan baru' ?><span class="accent">.</span></h1><p>Mulai dari judul singkat. Lengkapi detailnya sambil berjalan.</p></div></section>
<form class="editor-grid" method="post" action="<?= e(url('admin/save.php')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><div class="panel editor-main"><?php foreach ($errors as $error): ?><div class="notice error" role="alert"><?= e($error) ?></div><?php endforeach; ?><label>Judul pekerjaan <span class="required">*</span><input autofocus name="title" maxlength="120" required placeholder="Apa yang kamu kerjakan?" value="<?= e($log['title']) ?>"></label><div class="form-row"><label>Tanggal<input type="date" name="log_date" required value="<?= e($log['log_date']) ?>"></label><label>Proyek / kategori<select name="category_id"><option value="">Tanpa proyek</option><?php foreach (categories() as $category): ?><option value="<?= (int)$category['id'] ?>" <?= (string)$log['category_id'] === (string)$category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></label></div><label>Deskripsi<textarea name="description" rows="8" placeholder="Ceritakan proses, hasil, atau hal yang perlu diketahui…"><?= e($log['description']) ?></textarea></label><label>Tautan terkait<textarea name="links" rows="3" placeholder="https://… (satu tautan per baris)"><?= e($log['links']) ?></textarea></label></div><aside class="panel editor-settings"><h2>Status & publikasi</h2><label>Status<select name="status" id="status"><?php foreach (statuses() as $key=>$label): ?><option value="<?= e($key) ?>" <?= $log['status']===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Progres (%)<input type="number" name="progress" id="progress" min="0" max="100" required value="<?= (int)$log['progress'] ?>"></label><label>Catatan kendala<textarea name="blocker_note" id="blocker-note" rows="3" placeholder="Wajib untuk status terkendala"><?= e($log['blocker_note']) ?></textarea></label><label>Visibilitas<select name="visibility"><option value="public" <?= $log['visibility']==='public' ? 'selected' : '' ?>>Publik — terlihat semua orang</option><option value="private" <?= $log['visibility']==='private' ? 'selected' : '' ?>>Privat — hanya saya</option></select></label><p class="muted">Catatan privat hanya dapat dibuka setelah login.</p><button class="btn btn-primary full-width">Simpan catatan →</button><a class="btn full-width" href="<?= e(url('admin/')) ?>">Batal</a></aside></form>
<?php page_end(); ?>
